144	#[derive(Debug, PartialEq, Eq, Clone)]
145	enum ParseState<'a> {
146	    /// Parsing a value done, there is no state to record.
147	    ValueDone,
148	
149	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
150	    Pos((usize, usize)),
151	
152	    /// Parsing a optional flag argument
153	    Opt((&'a clap::Arg, usize)),
154	}
