536	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
537	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
538	fn longs_and_visible_aliases(
539	    p: &clap::Command,
540	    disabled: &HashSet<Id>,
541	) -> Vec<CompletionCandidate> {
542	    debug!("longs: name={}", p.get_name());
543	
544	    p.get_arguments()
545	        .filter(|a| !disabled.contains(a.get_id()))
546	        .filter_map(|a| {
547	            a.get_long_and_visible_aliases().map(|longs| {
548	                longs
549	                    .into_iter()
550	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
551	            })
552	        })
553	        .flatten()
554	        .collect()
555	}
556	
557	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
558	fn hidden_longs_aliases(p: &clap::Command, disabled: &HashSet<Id>) -> Vec<CompletionCandidate> {
559	    debug!("longs: name={}", p.get_name());
560	
561	    p.get_arguments()
562	        .filter(|a| !disabled.contains(a.get_id()))
563	        .filter_map(|a| {
564	            a.get_aliases().map(|longs| {
565	                longs.into_iter().map(|s| {
566	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
567	                })
568	            })
569	        })
570	        .flatten()
571	        .collect()
572	}
