574	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
575	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
576	fn shorts_and_visible_aliases(
577	    p: &clap::Command,
578	    disabled: &HashSet<Id>,
579	) -> Vec<CompletionCandidate> {
580	    debug!("shorts: name={}", p.get_name());
581	
582	    p.get_arguments()
583	        .filter(|a| !disabled.contains(a.get_id()))
584	        .filter_map(|a| {
585	            a.get_short_and_visible_aliases().map(|shorts| {
586	                shorts.into_iter().map(|s| {
587	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
588	                        a.get_help()
589	                            .cloned()
590	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
591	                    )
592	                })
593	            })
594	        })
595	        .flatten()
596	        .collect()
597	}
598	
599	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
600	    candidate
601	        .help(arg.get_help().cloned())
602	        .id(Some(format!("arg::{}", arg.get_id())))
603	        .tag(Some(
604	            arg.get_help_heading()
605	                .unwrap_or("Options")
606	                .to_owned()
607	                .into(),
608	        ))
609	        .display_order(Some(arg.get_display_order()))
610	        .hide(arg.is_hide_set())
611	}
