613	/// Get the possible values for completion
614	fn possible_values(
615	    a: &clap::Arg,
616	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
617	    if !a.get_num_args().expect("built").takes_values() {
618	        None
619	    } else {
620	        a.get_value_parser().possible_values()
621	    }
622	}
623	
624	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
625	///
626	/// Subcommand `rustup toolchain install` would be converted to
627	/// `("install", "rustup toolchain install")`.
628	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
629	    debug!("subcommands: name={}", p.get_name());
630	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
631	    p.get_subcommands()
632	        .flat_map(|sc| {
633	            sc.get_name_and_visible_aliases()
634	                .into_iter()
635	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
636	                .chain(sc.get_aliases().map(|s| {
637	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
638	                        .hide(true)
639	                }))
640	        })
641	        .collect()
642	}
643	
644	fn populate_command_candidate(
645	    candidate: CompletionCandidate,
646	    cmd: &clap::Command,
647	    subcommand: &clap::Command,
648	) -> CompletionCandidate {
649	    candidate
650	        .help(subcommand.get_about().cloned())
651	        .id(Some(format!("command::{}", subcommand.get_name())))
652	        .tag(Some(
653	            cmd.get_subcommand_help_heading()
654	                .unwrap_or("Commands")
655	                .to_owned()
656	                .into(),
657	        ))
658	        .display_order(Some(subcommand.get_display_order()))
659	        .hide(subcommand.is_hide_set())
660	}
661	
662	/// Parse the short flags and find the first `takes_values` option.
663	fn parse_shortflags<'c, 's>(
664	    cmd: &'c clap::Command,
665	    mut short: clap_lex::ShortFlags<'s>,
666	) -> (String, Option<&'c clap::Arg>, clap_lex::ShortFlags<'s>) {
667	    let takes_value_opt;
668	    let mut leading_flags = String::new();
669	    // Find the first takes_values option.
670	    loop {
671	        match short.next_flag() {
672	            Some(Ok(opt)) => {
673	                leading_flags.push(opt);
674	                let opt = cmd.get_arguments().find(|a| {
675	                    let shorts = a.get_short_and_visible_aliases();
676	                    let is_find = shorts.map(|v| {
677	                        let mut iter = v.into_iter();
678	                        let c = iter.find(|c| *c == opt);
679	                        c.is_some()
680	                    });
681	                    is_find.unwrap_or(false)
682	                });
683	                if opt
684	                    .map(|o| o.get_num_args().expect("built").takes_values())
685	                    .unwrap_or(false)
686	                {
687	                    takes_value_opt = opt;
688	                    break;
689	                }
690	            }
691	            Some(Err(_)) | None => {
692	                takes_value_opt = None;
693	                break;
694	            }
695	        }
696	    }
697	
698	    (leading_flags, takes_value_opt, short)
699	}
700	
701	/// Parse the positional arguments. Return the new state and the new positional index.
702	fn parse_positional<'a>(
703	    cmd: &clap::Command,
704	    pos_index: usize,
705	    is_escaped: bool,
706	    state: ParseState<'a>,
707	) -> (ParseState<'a>, usize) {
708	    let pos_arg = cmd
709	        .get_positionals()
710	        .find(|p| p.get_index() == Some(pos_index));
711	    let num_args = pos_arg
712	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
713	        .unwrap_or(1);
714	
715	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
716	        if num_args > 1 {
717	            (ParseState::Pos((pos_index, 1)), pos_index)
718	        } else {
719	            if is_escaped {
720	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
721	            } else {
722	                (ParseState::ValueDone, pos_index + 1)
723	            }
724	        }
725	    };
726	    match state {
727	        ParseState::ValueDone => {
728	            update_state_with_new_positional(pos_index)
729	        },
730	        ParseState::Pos((prev_pos_index, num_arg)) => {
731	            if prev_pos_index == pos_index {
732	                if num_arg + 1 < num_args {
733	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
734	                } else {
735	                    if is_escaped {
736	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
737	                    } else {
738	                        (ParseState::ValueDone, pos_index + 1)
739	                    }
740	                }
741	            } else {
742	                update_state_with_new_positional(pos_index)
743	            }
744	        }
745	        ParseState::Opt(..) => unreachable!(
746	            "This branch won't be hit,
747	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
748	        ),
749	    }
750	}
751	
752	/// Parse optional flag argument. Return new state
753	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
754	    let range = opt.get_num_args().expect("built");
755	    let max = range.max_values();
756	    if count < max {
757	        ParseState::Opt((opt, count + 1))
758	    } else {
759	        ParseState::ValueDone
760	    }
761	}
762	
763	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
764	    cmd.get_positionals()
765	        .find(|a| a.get_index() == Some(pos_index))
766	        .map(|p| p.is_allow_hyphen_values_set())
767	        .unwrap_or(false)
768	}
769	
770	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
771	    let val = arg.to_value_os();
772	    if val.starts_with("-") {
773	        if let ParseState::Opt((opt, _)) = state {
774	            return opt.is_allow_hyphen_values_set();
775	        }
776	    }
777	
778	    false
779	}
780	
781	/// Arguments that must not be offered because they conflict with an explicitly
782	/// present option. The present options themselves are never disabled.
783	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
784	    let mut disabled = HashSet::new();
785	    if explicit.is_empty() {
786	        return disabled;
787	    }
788	    for arg in cmd.get_arguments() {
789	        if explicit.contains(arg.get_id()) {
790	            // A present option hides everything it conflicts with ...
791	            for id in arg_direct_conflicts(cmd, arg) {
792	                if !explicit.contains(&id) {
793	                    disabled.insert(id);
794	                }
795	            }
796	        } else {
797	            // ... and is hidden when either side declares the conflict.
798	            if arg_direct_conflicts(cmd, arg)
799	                .iter()
800	                .any(|id| explicit.contains(id))
801	            {
802	                disabled.insert(arg.get_id().clone());
803	            }
804	        }
805	    }
806	    disabled
807	}
808	
809	/// Conflict partners of `arg`, following the same rules as clap's parser:
810	/// - the argument's own `conflicts_with` / `conflicts_with_all`
811	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
812	/// - the other members of non-`multiple` groups
813	///
814	/// Group ids are expanded to their argument members.
815	/// `overrides_with` relationships are intentionally not considered.
816	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
817	    let mut conflicts = arg
818	        .get_conflicts_with()
819	        .map(ToOwned::to_owned)
820	        .collect::<HashSet<_>>();
821	    for group in cmd.get_groups() {
822	        let members = unroll_group(cmd, group.get_id());
823	        if !members.iter().any(|m| m == arg.get_id()) {
824	            continue;
825	        }
826	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
827	        if !group.is_multiple_set() {
828	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
829	        }
830	    }
831	    conflicts
832	        .iter()
833	        .flat_map(|id| unroll_group(cmd, id))
834	        .collect()
835	}
836	
837	/// Resolve an argument or group id to its argument members.
838	/// Unknown ids resolve to themselves.
839	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
840	    let mut pending = vec![id.clone()];
841	    let mut args = Vec::new();
842	    while let Some(id) = pending.pop() {
843	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
844	            if !args.contains(&id) {
845	                args.push(id);
846	            }
847	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
848	            pending.extend(group.get_args().map(ToOwned::to_owned));
849	        } else if !args.contains(&id) {
850	            args.push(id);
851	        }
852	    }
853	    args
854	}
