        "-s [TAB]",
        "-ft [TAB]",
        "-tf [TAB]",
        "-t v1 -[TAB]",
        "-f -- [TAB]",
        "-ftv1 [TAB]",
        "-ft=v1 [TAB]",
        "-s -f [TAB]",
        "-fst [TAB]",
        "-tsf [TAB]",
        "-t v1 -f [TAB]",
        "-f -t v1 [TAB]",
        "-stv1 [TAB]",
        "-t v1 -- [TAB]",
        "-f sub [TAB]",
    ] {
        let mut cmd = command();
        println!("INPUT: {input:?} -> {:?}", complete(&mut cmd, input));
    }
}

